import { describe, expect, it } from 'vitest';
import { addressCall, burnToOctraData, readUint, verifyAndMintData } from '../abi';

// Expected values were produced by viem's encodeFunctionData with the same arguments.
const VIEM_MINT =
  '';
const VIEM_BURN =
  '';

describe('bridge calldata', () => {
  it('encodes verifyAndMint exactly like viem', () => {
    expect(
      verifyAndMintData({
        epoch: 123456,
        recipient: '0x9858EfFD232B4033E47d90003D41EC34EcaEda94',
        amountRaw: 2_500_000n,
        srcNonce: 42,
      })
    ).toBe(VIEM_MINT);
  });

  it('encodes burnToOctra exactly like viem', () => {
    expect(burnToOctraData('oct5MrNfjiXFNRDLwsodn8Zm9hDKNGAYt3eQDCQ52bSpCHq', 1_500_000n)).toBe(
      VIEM_BURN
    );
  });

  it('encodes allowance and reads uints', () => {
    expect(
      addressCall(
        '0xdd62ed3e',
        '0x9858EfFD232B4033E47d90003D41EC34EcaEda94',
        '0xE7eD69b852fd2a1406080B26A37e8E04e7dA4caE'
      )
    ).toBe(
      '0xdd62ed3e0000000000000000000000009858effd232b4033e47d90003d41ec34ecaeda94000000000000000000000000e7ed69b852fd2a1406080b26a37e8e04e7da4cae'
    );
    expect(readUint('0x' + '0'.repeat(62) + '2a')).toBe(42n);
    expect(readUint('0x')).toBe(0n);
    expect(() =>
      verifyAndMintData({ epoch: 1, recipient: '0x12', amountRaw: 1n, srcNonce: 1 })
    ).toThrow();
  });
});
